CREATE TABLE IF NOT EXISTS tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL, daily_limit INTEGER NOT NULL DEFAULT 100);
CREATE TABLE IF NOT EXISTS workspaces (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS venues (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), workspace_id TEXT NOT NULL REFERENCES workspaces(id), name TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'Asia/Shanghai');
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memberships (user_id TEXT PRIMARY KEY REFERENCES users(id), tenant_id TEXT NOT NULL REFERENCES tenants(id), role TEXT NOT NULL CHECK(role IN ('admin','editor','viewer')), workspace_ids TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf_token TEXT NOT NULL, expires_at TEXT NOT NULL, environment TEXT NOT NULL, app_env TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS uploads (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, workspace_id TEXT NOT NULL, owner_id TEXT NOT NULL, storage_key TEXT NOT NULL, sha256 TEXT NOT NULL, size INTEGER NOT NULL, media_type TEXT NOT NULL, specs TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assets (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, workspace_id TEXT NOT NULL, upload_id TEXT NOT NULL UNIQUE REFERENCES uploads(id), name TEXT NOT NULL, category TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, archived INTEGER NOT NULL DEFAULT 0, synthetic INTEGER NOT NULL DEFAULT 0, expires_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS asset_versions (asset_id TEXT NOT NULL REFERENCES assets(id), version INTEGER NOT NULL, snapshot TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(asset_id, version));
CREATE TABLE IF NOT EXISTS consents (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, workspace_id TEXT NOT NULL, asset_id TEXT NOT NULL REFERENCES assets(id), purpose TEXT NOT NULL, subject TEXT NOT NULL, proof TEXT NOT NULL, notice_version TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, workspace_id TEXT NOT NULL, actor_id TEXT NOT NULL, kind TEXT NOT NULL, payload TEXT NOT NULL, environment TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, max_attempts INTEGER NOT NULL DEFAULT 3, available_at TEXT NOT NULL, lease_token TEXT, lease_until TEXT, error_code TEXT, error_message TEXT, result TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS jobs_queue ON jobs(environment, status, available_at, lease_until);
CREATE TABLE IF NOT EXISTS outbox_events (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, workspace_id TEXT NOT NULL, aggregate_id TEXT NOT NULL, type TEXT NOT NULL, environment TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL, delivered_at TEXT);
CREATE TABLE IF NOT EXISTS event_deliveries (event_id TEXT PRIMARY KEY REFERENCES outbox_events(id), delivered_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS provider_usage (job_id TEXT PRIMARY KEY REFERENCES jobs(id), tenant_id TEXT NOT NULL, workspace_id TEXT NOT NULL, environment TEXT NOT NULL, units INTEGER NOT NULL, cost_minor INTEGER, currency TEXT NOT NULL DEFAULT 'CNY', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS provider_health (tenant_id TEXT NOT NULL, provider_id TEXT NOT NULL, failures INTEGER NOT NULL DEFAULT 0, open_until TEXT, PRIMARY KEY(tenant_id, provider_id));
CREATE TABLE IF NOT EXISTS profiles (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, workspace_id TEXT NOT NULL, name TEXT NOT NULL, avatar_asset_id TEXT NOT NULL REFERENCES assets(id), voice_asset_id TEXT REFERENCES assets(id), scenes TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profile_versions (profile_id TEXT NOT NULL REFERENCES profiles(id), version INTEGER NOT NULL, snapshot TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(profile_id, version));
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, workspace_id TEXT NOT NULL, actor_id TEXT NOT NULL, action TEXT NOT NULL, resource_id TEXT NOT NULL, outcome TEXT NOT NULL, request_id TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency (tenant_id TEXT NOT NULL, actor_id TEXT NOT NULL, action TEXT NOT NULL, key TEXT NOT NULL, request_hash TEXT NOT NULL, response TEXT NOT NULL, status_code INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(tenant_id, actor_id, action, key));
